ARTICLES = [
 dict(slug='family-documents', category='family', translations={
 'fa': ('برای بررسی یک اختلاف خانوادگی، از کجا شروع کنیم؟','پیش از انتخاب راه‌حل، شرح دقیق موضوع و مدارک را کنار هم بگذارید.', [
 ('مسئله و خواسته را جدا بنویسید','شرح اختلاف با خواسته شما یکسان نیست. ممکن است موضوع درباره جدایی، حقوق مالی یا فرزندان باشد، اما هدف فعلی شما فقط شناخت گزینه‌ها یا بررسی امکان توافق باشد. در شرح اولیه، مشخص کنید چه اتفاقی افتاده و چه نتیجه‌ای می‌خواهید. تاریخ‌های مهم و اقداماتی که قبلاً انجام شده نیز باید روشن باشد.'),
 ('مدارک را به ترتیب آماده کنید','مدارک هویتی، سند ازدواج و هر توافق مرتبط، نقطه شروع بررسی هستند. اگر پرونده‌ای مطرح شده، دادخواست، تصمیم‌های صادرشده و ابلاغ‌ها را نیز کنار هم قرار دهید. مکاتباتی که به موضوع مربوط‌اند می‌توانند در فهم وقایع مفید باشند، اما اهمیت حقوقی هر مدرک باید جداگانه بررسی شود. بهتر است اصل فایل‌ها حفظ شود و برای هر مدرک توضیح کوتاهی بنویسید.'),
 ('اگر خارج از ایران هستید','محل ازدواج، محل اقامت طرفین و اینکه موضوع در کدام کشور مطرح شده، در بررسی اولیه اهمیت دارد. وجود تصمیم یا سند خارجی به‌تنهایی پاسخ همه پرسش‌ها درباره آثار آن در ایران نیست. مدارک خارجی، ترجمه‌ها و هر اقدامی که برای ثبت یا تأیید انجام شده را معرفی کنید. درباره امکان اقدام با وکالت و موارد نیازمند حضور، باید بر اساس همان پرونده تصمیم گرفت.'),
 ('پیش از شروع همکاری روشن کنید','دامنه بررسی، اقدامات مورد توافق، هزینه‌ها و نحوه اطلاع‌رسانی باید مشخص باشد. زمان‌بندی قطعی یا نتیجه تضمینی را جایگزین ارزیابی واقعی نکنید. یک بررسی مفید باید پرسش‌های باقی‌مانده را هم نشان دهد، نه اینکه تنها یک پاسخ فوری و کلی ارائه کند.')]),
 'ar': ('كيف تبدأ دراسة نزاع أسري؟','رتّب الوقائع والمستندات قبل اختيار الخطوة التالية.', [
 ('افصل بين الوقائع والهدف','وصف الخلاف ليس هو النتيجة التي تريدها. قد تتعلق المسألة بالانفصال أو الحقوق المالية أو الأطفال، بينما يكون هدفك الحالي فهم الخيارات أو بحث التسوية. اشرح ما حدث وما تريده، وحدد التواريخ المهمة والإجراءات السابقة.'),
 ('رتّب المستندات','تُعد وثائق الهوية وعقد الزواج وأي اتفاق ذي صلة بداية للمراجعة. إذا كان هناك ملف قائم، أضف الطلبات والقرارات والإخطارات. قد تساعد المراسلات ذات الصلة في فهم الوقائع، لكن يجب تقييم أهمية كل وثيقة قانونياً. احتفظ بالملفات الأصلية وأرفق شرحاً مختصراً لكل مستند.'),
 ('إذا كنت خارج إيران','يهم في الدراسة الأولية مكان الزواج وإقامة الطرفين والدولة التي طُرحت فيها المسألة. لا يجيب وجود قرار أو مستند أجنبي وحده عن جميع الأسئلة المتعلقة بآثاره في إيران. وضّح المستندات والترجمات وإجراءات التسجيل أو التصديق السابقة. تُدرس إمكانية المتابعة بالوكالة والحاجة إلى الحضور وفق الحالة.'),
 ('قبل بدء التعاون','حدّد نطاق المراجعة والإجراءات المتفق عليها والأتعاب وطريقة التواصل. لا تستبدل التقييم الواقعي بوعد بموعد أو نتيجة مؤكدة. ينبغي أن تكشف المراجعة الجيدة الأسئلة التي ما زالت تحتاج إلى إجابة.')]),
 'en': ('Where to begin with a family dispute','Organise the facts and documents before deciding on a course of action.', [
 ('Separate the facts from your objective','The dispute and the outcome you want are not the same thing. The issue may involve separation, financial rights or children, while your immediate goal is simply to understand your options or explore an agreement. Explain what happened and what you want, including relevant dates and previous steps.'),
 ('Organise the documents','Identity records, marriage documents and any relevant agreements are a starting point. For an existing case, include applications, decisions and notices. Correspondence may help explain events, but its legal significance needs individual review. Preserve original files and provide a brief explanation of each document.'),
 ('When you are outside Iran','The place of marriage, the parties’ residence and the country where proceedings have taken place matter to the initial review. A foreign document or decision does not, by itself, answer every question about its effects in Iran. Identify translations and any prior registration or authentication steps. Representation and any attendance requirements need case-specific assessment.'),
 ('Before engaging a lawyer','Clarify the scope of review, agreed steps, fees and communication arrangements. A guaranteed timeline or outcome is not a substitute for a realistic assessment. A useful review should identify unanswered questions as well as possible next steps.')])}),
 dict(slug='inheritance-review', category='inheritance', translations={
 'fa': ('برای بررسی امور ارث، چه اطلاعاتی آماده کنیم؟','وراث، دارایی‌ها و اقدامات قبلی را پیش از شروع پیگیری مشخص کنید.', [
 ('از تصویر کامل موضوع شروع کنید','برای بررسی اولیه، تاریخ و محل فوت، نسبت اشخاص با متوفی و وضعیت شناخته‌شده وراث را توضیح دهید. اگر درباره هویت وراث یا سهم اشخاص اختلافی وجود دارد، همان اختلاف باید از ابتدا مطرح شود. تعیین سهم و مسیر اقدام به اطلاعات و مدارک معتبر نیاز دارد و با یک شرح کوتاه قطعی نمی‌شود.'),
 ('دارایی‌ها و تعهدات را معرفی کنید','فهرستی از اموال شناخته‌شده، اسناد مالکیت، حساب‌ها و مطالبات احتمالی تهیه کنید. بدهی‌ها، وصیت‌نامه احتمالی و قراردادهای مرتبط نیز در بررسی اهمیت دارند. این فهرست برای شروع است و لزوماً به معنای احراز مالکیت یا کامل بودن ترکه نیست. درباره اموالی که اطلاعات ناقص دارند، حدس را از سند جدا کنید.'),
 ('اقدامات قبلی را فراموش نکنید','هر گواهی، تصمیم، توافق تقسیم، انتقال یا پرونده قبلی را معرفی کنید. اگر یکی از وراث امور را پیگیری کرده، مشخص کنید چه اختیاری داشته و چه اقداماتی انجام داده است. مدارک مربوط به دارایی‌های خارج از ایران یا فوت در خارج نیز باید جداگانه بررسی شوند. تشریفات مورد نیاز به محل صدور مدارک و نوع اقدام بستگی دارد.'),
 ('حدود نمایندگی را دقیق مشخص کنید','پیگیری اداری، دریافت مدارک، توافق با وراث و فروش یا انتقال اموال، کارهای یکسانی نیستند. پیش از امضای وکالت‌نامه، موضوع و حدود اختیار را متناسب با هدف خود بررسی کنید. برای متن وکالت‌نامه و الزامات تصدیق آن، راهنمای نمایندگی کنسولی مربوط و نظر وکیل را همزمان در نظر بگیرید.')]),
 'ar': ('ما المعلومات اللازمة لدراسة مسائل الميراث؟','حدّد الورثة والأموال والخطوات السابقة قبل بدء المتابعة.', [
 ('ابدأ بصورة كاملة','اشرح تاريخ الوفاة ومكانها وصلة الأشخاص بالمتوفى ووضع الورثة المعروف. إذا كان هناك خلاف حول الورثة أو حصصهم، اذكره من البداية. يتطلب تحديد الحصص والمسار معلومات ومستندات موثوقة، ولا يُحسم من وصف مختصر.'),
 ('عرّف بالأموال والالتزامات','أعد قائمة بالأموال المعروفة ووثائق الملكية والحسابات والمطالبات المحتملة. وتهم أيضاً الديون والوصية المحتملة والعقود ذات الصلة. هذه قائمة أولية وليست إثباتاً للملكية أو اكتمال التركة. افصل بين المعلومات الموثقة والتخمين.'),
 ('اذكر الإجراءات السابقة','قدّم الشهادات والقرارات واتفاقات القسمة والتحويلات أو الملفات السابقة. إذا تابع أحد الورثة الموضوع، وضّح صلاحياته وما فعله. تُراجع على حدة وثائق الأموال الأجنبية أو الوفاة في الخارج. تعتمد الإجراءات اللازمة على جهة إصدار الوثائق وطبيعة العمل.'),
 ('حدّد صلاحيات الوكالة','المتابعة الإدارية واستلام الوثائق والتسوية مع الورثة وبيع الأموال ليست إجراءات متطابقة. راجع موضوع الوكالة وصلاحياتها قبل التوقيع. واستعن بإرشادات القنصلية المعنية ورأي المحامي عند إعداد النص والتحقق من متطلبات التصديق.')]),
 'en': ('What to prepare for an inheritance review','Identify the heirs, known assets and previous steps before pursuing the matter.', [
 ('Start with the full picture','Explain the date and place of death, relationships to the deceased and the known position of the heirs. Disputes about heirs or shares should be raised at the outset. Reliable information and documents are needed to assess entitlements and next steps; a short account is not enough for a definitive answer.'),
 ('Identify assets and obligations','Prepare a list of known assets, ownership records, accounts and possible receivables. Debts, a possible will and relevant contracts also matter. An initial list does not prove ownership or establish a complete estate. Distinguish documented information from assumptions.'),
 ('Include previous work','Identify certificates, decisions, division agreements, transfers and previous proceedings. If an heir has handled the matter, explain their authority and actions. Foreign assets and documents relating to a death abroad need separate consideration. Requirements depend on where documents were issued and the proposed action.'),
 ('Define authority carefully','Administrative follow-up, collecting documents, reaching agreements with heirs and selling assets are different activities. Review the scope of a power of attorney against your objective before signing. Consider the relevant consulate’s guidance and a lawyer’s review of the wording and authentication requirements.')])}),
 dict(slug='property-power-of-attorney', category='property', translations={
 'fa': ('پیش از دادن وکالت برای امور ملک چه چیزهایی را روشن کنیم؟','اختیار پیگیری، فروش و دریافت وجه را یکسان فرض نکنید.', [
 ('هدف وکالت را دقیق بنویسید','ابتدا مشخص کنید نماینده قرار است چه کاری انجام دهد. دریافت یک سند، پیگیری اختلاف، اجاره دادن و فروش ملک اهداف متفاوتی هستند. اعتماد شخصی جای متن دقیق را نمی‌گیرد. بهتر است هدف، ملک مورد نظر و اقداماتی که واقعاً لازم است، پیش از تنظیم وکالت‌نامه روشن شود.'),
 ('اختیارات را جدا بررسی کنید','اختیار امضا، توافق بر قیمت، دریافت وجه، تحویل ملک و سپردن اختیار به شخص دیگر باید با توجه به هدف بررسی شود. درباره هر اختیار بپرسید آیا برای کار مورد نظر لازم است و چه اثری دارد. استفاده از متن عمومی بدون شناخت آثار آن ممکن است دامنه اختیار را از خواسته شما فراتر ببرد.'),
 ('مدارک ملک و وضعیت تصرف را مشخص کنید','سند، قراردادهای قبلی، اطلاعات شریک‌ها، اجاره‌نامه و مدارک پرونده‌های مرتبط را معرفی کنید. تفاوت میان ادعای مالکیت، مدرک موجود و وضعیت واقعی تصرف باید روشن باشد. صرف داشتن وکالت‌نامه پاسخ همه مسائل مالکیت یا اختلافات ملک نیست.'),
 ('از خارج کشور با هماهنگی اقدام کنید','پیش از ثبت یا امضای متن، آن را با شخص یا مرجعی که قرار است در ایران از آن استفاده کند بررسی کنید. راهنمای کنسولی، احراز هویت و تصدیق امضا با کفایت حقوقی متن برای اقدام مورد نظر یکی نیست. کانال گزارش‌دهی و نحوه ثبت هزینه‌ها را نیز پیش از شروع همکاری مشخص کنید.')]),
 'ar': ('ما الذي ينبغي توضيحه قبل منح وكالة عقارية؟','لا تفترض أن المتابعة والبيع واستلام المال صلاحية واحدة.', [
 ('حدّد الهدف بدقة','وضّح ما الذي سيقوم به الوكيل. استلام مستند ومتابعة نزاع والتأجير والبيع أهداف مختلفة. الثقة الشخصية لا تغني عن نص دقيق. حدّد العقار والهدف والإجراءات اللازمة قبل إعداد الوكالة.'),
 ('راجع الصلاحيات منفصلة','راجع صلاحيات التوقيع والاتفاق على السعر واستلام المال وتسليم العقار وتفويض شخص آخر وفق هدفك. اسأل عن ضرورة كل صلاحية وآثارها. قد يمنح النص العام صلاحيات أوسع مما قصدت إذا استُخدم دون مراجعة.'),
 ('وضّح المستندات والحيازة','قدّم سند الملكية والعقود السابقة ومعلومات الشركاء والإيجار والملفات ذات الصلة. يجب التمييز بين ادعاء الملكية والمستندات والوضع الفعلي لشاغلي العقار. لا تعالج الوكالة وحدها جميع مسائل الملكية والنزاع.'),
 ('نسّق قبل التوقيع من الخارج','راجع النص قبل تسجيله أو توقيعه مع الشخص أو الجهة التي ستستخدمه في إيران. إرشادات القنصلية والتحقق من الهوية والتصديق على التوقيع تختلف عن كفاية النص القانونية للعمل المطلوب. حدّد أيضاً التقارير وطريقة توثيق المصروفات قبل بدء التعاون.')]),
 'en': ('Before granting a property power of attorney','Authority to follow up, sell and receive money should not be treated as one thing.', [
 ('Define the purpose','Specify what the representative will do. Obtaining a document, pursuing a dispute, letting a property and selling it are different objectives. Personal trust does not replace precise wording. Identify the property, objective and genuinely necessary steps before preparing the document.'),
 ('Review each power separately','Consider signing authority, price negotiation, receipt of money, delivery of possession and delegation to others in light of your objective. Ask whether each power is necessary and what it permits. General wording can extend authority beyond your intention if used without review.'),
 ('Explain records and occupation','Identify ownership records, earlier contracts, co-owners, leases and related case documents. Distinguish the claim to ownership, available evidence and actual occupation. A power of attorney does not, by itself, resolve all title or property disputes.'),
 ('Coordinate before signing abroad','Before registration or signature, review the wording with the person or authority expected to use it in Iran. Consular procedures, identity checks and signature authentication differ from whether the wording is legally sufficient for the intended action. Agree on reporting and expense records before work begins.')])})
]

ICONS={
 'family':'<circle cx="9" cy="7" r="3"/><circle cx="17" cy="9" r="2.5"/><path d="M3 21v-4a6 6 0 0 1 12 0v4m1-7a5 5 0 0 1 5 5v2"/>',
 'inheritance':'<path d="M7 3h11a2 2 0 0 1 2 2v16H7a3 3 0 0 1-3-3V6a3 3 0 0 1 3-3Zm0 0v18M11 8h5m-5 4h5m-5 4h3"/>',
 'property':'<path d="m3 11 9-8 9 8M5 10v11h14V10m-10 11v-7h6v7"/>',
 'chat':'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5H5l-3 2 1-6a8.5 8.5 0 1 1 18-4.5Z"/><path d="M8 9h8m-8 4h5"/>'}
def icon(name):
 if name == 'chat': return '<svg viewBox="0 0 32 32" fill="currentColor" aria-hidden="true"><path d="M16 3a13 13 0 0 0-11.2 19.6L3 29l6.6-1.7A13 13 0 1 0 16 3Zm0 2.4A10.6 10.6 0 1 1 10.5 25l-.8-.5-3.3.9.9-3.3-.5-.8A10.6 10.6 0 0 1 16 5.4Z"/><path d="M12 9.5c-.3-.6-.6-.6-.9-.6h-.7c-.3 0-.7.1-1 .5-.4.4-1.3 1.3-1.3 3.1s1.3 3.5 1.5 3.8c.2.2 2.7 4.1 6.5 5.5 3.2 1.2 3.8.9 4.5.8.7-.1 2.2-.9 2.5-1.8.3-.9.3-1.7.2-1.8-.1-.2-.4-.3-.8-.5l-2.4-1.1c-.3-.2-.6-.2-.8.2l-1.1 1.3c-.2.2-.4.3-.8.1-.4-.2-1.6-.6-3.1-1.9-1.1-1-1.9-2.2-2.1-2.6-.2-.3 0-.5.2-.7l.6-.7.4-.6c.1-.2 0-.5 0-.7l-1.1-2.8Z"/></svg>'
 return f'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{ICONS[name]}</svg>'
def url(lang, path=''): return f'/{lang}/'+path
def e(s): return escape(s,quote=True)

def header(lang,path=''):
 t=TEXT[lang]
 langs=''.join(f'<a href="{url(l,path)}" lang="{l}" aria-label="{ {"fa":"فارسی","ar":"العربية","en":"English"}[l]}" {"aria-current=\"page\"" if l==lang else ""}>{l.upper()}</a>' for l in ['fa','en','ar'])
 caption='NADER JAFARY' if lang=='en' else 'DAADER'
 return f'''<a class="skip" href="#main">{t['journal']}</a><header class="site-header"><div class="nav-wrap"><a class="brand" href="{url(lang)}"><span class="brand-name">{t['brand']}</span><span class="brand-caption">{caption}</span></a><nav id="navigation" aria-label="{t['home']}"><a href="{url(lang)}#services">{t['services']}</a><a href="{url(lang,'about/')}">{t['about']}</a><a href="{url(lang,'articles/')}">{t['journal']}</a></nav><div class="nav-actions"><div class="languages">{langs}</div><button class="menu-button" aria-label="{t['menu']}" aria-expanded="false" aria-controls="navigation"><span></span><span></span></button></div></div></header>'''

def footer(lang):
 t=TEXT[lang]
 return f'''<footer><div class="footer-top wrap"><div><span class="eyebrow">DAADER</span><h2>{t['footer_title']}</h2><p>{t['footer_sub']}</p></div><button class="button whatsapp-button" data-contact>{icon('chat')}{t['whatsapp']}</button></div><div class="footer-bottom wrap"><a class="footer-brand" href="{url(lang)}">{t['brand']}</a><span>{t['copyright']}</span><span>{t['footer_note']}</span></div></footer>'''

def contact_dock(lang):
 t=TEXT[lang]
 return f'''<aside class="contact-dock" aria-label="WhatsApp"><div class="dock-wrap"><button class="dock-contact" data-contact aria-label="WhatsApp +{WHATSAPP_NUMBER}">{icon('chat')}<span>WhatsApp</span></button><span class="dock-note">{t['footer_note']}</span></div></aside>'''

def shell(lang,title,desc,body,path=''):
 t=TEXT[lang]
 alts=''.join(f'<link rel="alternate" hreflang="{l}" href="{ORIGIN}{url(l,path)}">' for l in LANGS)
 page = f'''<!doctype html><html lang="{lang}" dir="{t['dir']}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)}</title><meta name="description" content="{e(desc)}"><meta name="theme-color" content="#F3F0E9"><link rel="canonical" href="{ORIGIN}{url(lang,path)}">{alts}<link rel="icon" type="image/svg+xml" href="/assets/favicon.svg?v={ASSET_VERSION}"><link rel="preload" href="/assets/vazirmatn-400.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="/assets/style.css?v={ASSET_VERSION}"><script src="/assets/site.js?v={ASSET_VERSION}" defer></script></head><body data-lang="{lang}"><div class="site-scroll">{header(lang,path)}<main id="main">{body}</main>{footer(lang)}</div>{contact_dock(lang)}</body></html>'''
 return re.sub(r'<button([^>]*\bdata-contact[^>]*)>(.*?)</button>', lambda m: '<a'+m[1]+f' href="https://wa.me/{WHATSAPP_NUMBER}" target="_blank" rel="noopener noreferrer">'+m[2]+'</a>', page, flags=re.S)

def cards(lang,articles=ARTICLES):
 t=TEXT[lang]
 return ''.join(f'''<a class="note-card" href="{url(lang,'articles/'+a['slug']+'/')}"><span class="note-cat">{t[a['category']]}</span><h3>{a['translations'][lang][0]}</h3><p>{a['translations'][lang][1]}</p><span class="text-link">{t['article_link']}</span></a>''' for a in articles)

def home(lang):
 t=TEXT[lang]
 name_role=t['name']+(' · ' if lang=='en' else '، ')+t['role']
 digits=str.maketrans('0123456789','۰۱۲۳۴۵۶۷۸۹') if lang=='fa' else str.maketrans('0123456789','٠١٢٣٤٥٦٧٨٩') if lang=='ar' else {}
 arrow='←' if t['dir']=='rtl' else '→'
 service_cards=''.join(f'''<a class="service-card" href="{url(lang,'articles/'+a['slug']+'/')}"><span class="service-number" aria-hidden="true">{f'{i+1:02}'.translate(digits)}</span><h3>{t[a['category']]}</h3><p>{t[a['category']+'_desc']}</p><span class="text-link">{t['service_link']} <span aria-hidden="true">{arrow}</span></span></a>''' for i,a in enumerate(ARTICLES))
 steps=''.join(f'<div class="step"><span class="step-no">0{i+1}</span><h3>{s[0]}</h3><p>{s[1]}</p></div>' for i,s in enumerate(t['steps']))
 return shell(lang,t['title'],t['intro'],f'''<section class="hero"><div class="hero-copy"><p class="hero-kicker">{name_role}</p><h1>{t['hero']}</h1><p class="hero-intro">{t['intro']}</p><p class="hero-sub">{t['degree']}</p><a class="button primary" href="#services">{t['explore']}</a></div><figure class="hero-photo"><img class="hero-image" src="/assets/courthouse.webp" alt="" fetchpriority="high" width="1448" height="1086"></figure></section><section class="practice wrap" id="services"><h2 class="sr-only">{t['practice_label']}</h2><div class="services-grid">{service_cards}</div></section><section class="about-band"><div class="wrap about-grid"><div class="about-heading"><span class="eyebrow">{t['about_label']}</span><h2>{t['about_title']}</h2><p class="degree">{t['degree']}</p></div><div class="about-copy"><p>{t['bio']}</p><a class="text-link" href="{url(lang,'about/')}">{t['about_link']} <span aria-hidden="true">{arrow}</span></a></div></div></section><section class="process section wrap"><div class="slim-heading"><span class="eyebrow">{t['approach']}</span><span class="section-rule"></span></div><div class="steps-grid">{steps}</div></section><section class="journal-section section"><div class="wrap"><div class="section-heading"><div><span class="eyebrow">{t['journal_label']}</span><h2>{t['journal_title']}</h2></div><a class="text-link" href="{url(lang,'articles/')}">{t['all_articles']}</a></div><div class="notes-grid">{cards(lang)}</div></div></section>''')

def index(lang):
 t=TEXT[lang]
 return shell(lang,t['journal']+' | '+t['brand'],t['journal'],f'''<section class="page-head wrap"><span class="eyebrow">DAADER JOURNAL</span><h1>{t['journal']}</h1><p>{t['journal_title'].replace('<br>',' ')}</p></section><section class="wrap article-list"><div class="notes-grid">{cards(lang)}</div></section>''','articles/')

def about(lang):
 t=TEXT[lang]
 sections=''.join(f'<section><h2>{s[0]}</h2><p>{s[1]}</p></section>' for s in t['about_sections'])
 return shell(lang,t['about']+' | '+t['name'],t['degree'],f'''<section class="page-head wrap"><span class="eyebrow">{t['about_label']}</span><h1>{t['name']}</h1><p>{t['degree']}</p></section><div class="wrap about-page"><div class="about-profile"><span class="eyebrow">{t['role']}</span><strong>{t['name']}</strong><p>{t['degree']}</p></div><div class="about-body"><h2>{t['about_intro']}</h2><p>{t['bio']}</p><p>{t['bio2']}</p>{sections}<a class="text-link" href="https://naderjafari.com/" target="_blank" rel="noopener noreferrer">{t['competition']}</a></div></div>''','about/')

def article(lang,a):
 t=TEXT[lang];title,desc,sections=a['translations'][lang]
 toc=''.join(f'<a href="#part-{i}">{s[0]}</a>' for i,s in enumerate(sections))
 content=''.join(f'<section id="part-{i}"><h2>{s[0]}</h2><p>{s[1]}</p></section>' for i,s in enumerate(sections))
 return shell(lang,title+' | '+t['brand'],desc,f'''<header class="article-head wrap"><a class="breadcrumb" href="{url(lang,'articles/')}">{t['journal']}</a><span class="note-cat">{t[a['category']]}</span><h1>{title}</h1><p>{desc}</p><div class="article-meta"><span>{t['name']}</span><span>{t['date']}</span><span>{t['reading']}</span></div></header><div class="article-surface"><div class="wrap article-layout"><article class="prose">{content}<div class="article-disclaimer">{t['disclaimer']}</div><section class="article-end-contact"><span class="eyebrow">{t['article_contact']}</span><p>{t['article_contact_desc']}</p><button class="button gold" data-contact>{icon('chat')}{t['whatsapp']}</button></section></article><aside class="article-sidebar"><div class="sidebar-inner"><h2>{t['contents']}</h2><nav>{toc}</nav><div class="author-card"><span class="mini-monogram">NJ</span><h3>{t['name']}</h3><p>{t['role']}</p><a href="{url(lang,'about/')}">{t['about']}</a></div><button class="button sidebar-contact" data-contact>{icon('chat')}{t['whatsapp']}</button></div></aside></div></div><section class="section wrap"><div class="slim-heading"><h2>{t['related']}</h2></div><div class="notes-grid two">{cards(lang,[x for x in ARTICLES if x!=a])}</div></section>''','articles/'+a['slug']+'/')

def write(path,content):
 p=OUT/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content,encoding='utf8')
for lang in LANGS:
 write(Path(lang)/'index.html',home(lang))
 write(Path(lang)/'about/index.html',about(lang))
 write(Path(lang)/'articles/index.html',index(lang))
 for a in ARTICLES:write(Path(lang)/'articles'/a['slug']/'index.html',article(lang,a))
write(Path('index.html'),home('fa'))
write(Path('assets/contact.json'),json.dumps({'whatsapp':WHATSAPP_NUMBER,'email':''})+'\n')
write(Path('404.html'),'<html lang="fa" dir="rtl"><meta charset="utf-8"><title>صفحه پیدا نشد | دادر</title><link rel="stylesheet" href="/assets/style.css"><main class="page-head wrap"><h1>صفحه پیدا نشد</h1><a class="button gold" href="/fa/">بازگشت به دادر</a></main></html>')
write(Path('robots.txt'),'User-agent: *\nAllow: /\nSitemap: '+ORIGIN+'/sitemap.xml\n')
paths=['']+[f'{l}/{p}' for l in LANGS for p in ['', 'about/', 'articles/']+[f'articles/{a["slug"]}/' for a in ARTICLES]]
write(Path('sitemap.xml'),'<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{ORIGIN}/{p}</loc></url>' for p in paths)+'</urlset>')
write(Path('CNAME'),'daader.ir\n')
write(Path('.nojekyll'),'')
print('Created homepage, about, article index and 3 legal notes in 3 languages.')
